cd /workdir && python3 - <<'EOF'
import csv, re
from decimal import Decimal
rows=list(csv.reader(open('input.csv',newline='',encoding='utf-8')))
h=rows[0]; d=rows[1:]
print(h, len(d))
from collections import Counter
print(Counter(len(r) for r in d))
ids=[r[0] for r in d]
print('unique ids', len(set(ids)))
print('sorted order?', ids==sorted(ids))
bad=[(i+1,r) for i,r in enumerate(d) if not re.fullmatch(r'D\d{5}',r[0])]
print('bad ids', bad[:10], len(bad))
print(Counter(r[3] for r in d))
for i,r in enumerate(d):
    issues=[]
    if len(r)!=5: issues.append('len')
    else:
        if not (1<=len(r[1])<=80): issues.append('account len')
        if not (1<=len(r[2])<=80): issues.append('owner len')
        if r[1]!=r[1].strip() or r[2]!=r[2].strip(): issues.append('whitespace')
        try:
            a=Decimal(r[4])
            if not (0<a<=1000000) or a!=a.quantize(Decimal('0.01')): issues.append('amount range '+r[4])
            if not re.fullmatch(r'\d+\.\d\d',r[4]): issues.append('amount fmt '+r[4])
        except Exception: issues.append('amount parse '+r[4])
        if any(ord(c)>127 for c in ''.join(r)): issues.append('nonascii')
        if any(c in ''.join(r) for c in '"\\\n\r\t'): issues.append('special')
    if issues: print(i+1, r, issues)
EOF
